import { supabase } from '../lib/supabase'
import type { TrainingPlan, TrainingPlanInsert, TrainingPlanUpdate } from '../types/database'
import { isFmPathOverlap, parseFmUrl } from '../utils/unit-utils'

import { deleteLearningHistoriesByDirectory } from './learningHistories'

export async function getTrainingPlans(userId?: string): Promise<TrainingPlan[]> {
  let query = supabase.from('training_plans').select('*').order('created_at', { ascending: false })

  if (userId) {
    query = query.eq('user_id', userId)
  }

  const { data, error } = await query

  if (error) throw error
  return data ?? []
}

export async function getTrainingPlan(id: number, userId?: string): Promise<TrainingPlan | null> {
  let query = supabase.from('training_plans').select('*').eq('id', id)

  if (userId) {
    query = query.eq('user_id', userId)
  }

  const { data, error } = await query.single()

  if (error) throw error
  return data
}

export async function createTrainingPlan(plan: TrainingPlanInsert): Promise<TrainingPlan> {
  const { data, error } = await supabase.from('training_plans').insert(plan).select().single()

  if (error) throw error
  return data
}

export async function updateTrainingPlan(
  id: number,
  plan: TrainingPlanUpdate
): Promise<TrainingPlan> {
  const { data, error } = await supabase
    .from('training_plans')
    .update({ ...plan, updated_at: new Date().toISOString() })
    .eq('id', id)
    .select()
    .single()

  if (error) throw error
  return data
}

export async function deleteTrainingPlan(id: number): Promise<void> {
  // fm:// 훈련 계획이면 연관된 learning_histories도 함께 삭제한다.
  // user_id를 함께 넘겨야 한다. 관리자 계정은 RLS가 열려 있어 조건이 없으면
  // 같은 경로를 쓰는 다른 사용자의 이력까지 지운다.
  const plan = await getTrainingPlan(id)
  const fmInfo = plan ? parseFmUrl(plan.unit_name) : null
  if (plan && fmInfo) {
    await deleteLearningHistoriesByDirectory(fmInfo.owner, fmInfo.repo, fmInfo.path, plan.user_id)
  }

  const { error } = await supabase.from('training_plans').delete().eq('id', id)

  if (error) throw error
}

/**
 * 같은 사용자의 fm:// 플랜 중 unitName 과 경로가 같거나 상하위 관계인 것을 찾는다.
 * 생성/수정 폼의 사전 검사용. DB 제약(018)과 같은 규칙.
 */
export async function findOverlappingFmPlans(
  userId: string,
  unitName: string,
  excludeId?: number
): Promise<TrainingPlan[]> {
  const fmInfo = parseFmUrl(unitName)
  if (!fmInfo) return []

  const { data, error } = await supabase
    .from('training_plans')
    .select('*')
    .eq('user_id', userId)
    .like('unit_name', `fm://${fmInfo.owner}/${fmInfo.repo}%`)

  if (error) throw error
  return (data ?? []).filter((p) => p.id !== excludeId && isFmPathOverlap(p.unit_name, unitName))
}

/** Postgres unique_violation. 018 의 경로 유일성 제약(인덱스·트리거 모두)이 이 코드로 실패한다. */
export function isUniqueViolation(err: unknown): boolean {
  return typeof err === 'object' && err !== null && (err as { code?: string }).code === '23505'
}
